package com.bank.kafkaflow;

import org.apache.kafka.clients.producer.*;
import org.apache.kafka.clients.consumer.*;
import org.apache.kafka.common.serialization.*;
import java.math.BigDecimal;
import java.time.Duration;
import java.util.*;
import java.util.logging.*;

// This file contains multiple classes for the runnable demo.
// In a real project each would live in its own file.
public class KafkaFlowDemo {
    private static final Logger log = Logger.getLogger(KafkaFlowDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // ---- PRODUCER configuration (the three mandatory + acks) ----
        Properties p = new Properties();
        p.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, "broker1:9092,broker2:9092");
        p.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        p.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        p.put(ProducerConfig.ACKS_CONFIG, "all");                 // durability
        p.put(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG, "true");  // no duplicates on retry

        TransferEvent event = new TransferEvent("SAV2001", "CUR3001", new BigDecimal("50000"));
        // The key (account) decides the partition so all of Rajesh's events stay ordered.
        try (Producer<String, String> producer = new KafkaProducer<>(p)) {
            ProducerRecord<String, String> record =
                new ProducerRecord<>("transfers", event.getFromAccount(), event.toJson());
            producer.send(record, (meta, ex) -> {
                if (ex != null) log.log(Level.SEVERE, "Transfer publish failed", ex);
                else log.info(() -> "Published to partition " + meta.partition()
                        + " offset " + meta.offset());
            });
            producer.flush();
        }

        // ---- CONSUMER configuration (servers + deserializers + group) ----
        Properties c = new Properties();
        c.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "broker1:9092,broker2:9092");
        c.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
        c.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
        c.put(ConsumerConfig.GROUP_ID_CONFIG, "settlement-service");
        c.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, "earliest"); // read backlog for a new group
        c.put(ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG, "false");   // commit only after processing

        try (Consumer<String, String> consumer = new KafkaConsumer<>(c)) {
            consumer.subscribe(List.of("transfers"));
            ConsumerRecords<String, String> records = consumer.poll(Duration.ofSeconds(5));
            for (ConsumerRecord<String, String> rec : records) {
                log.info(() -> "Settling transfer: " + rec.value());
                // ... apply the transfer to the ledger here ...
                consumer.commitSync();  // at-least-once: commit AFTER success
            }
        }
    }
}

