class TransferEvent {
    private final String fromAccount;
    private final String toAccount;
    private final BigDecimal amount;
    TransferEvent(String from, String to, BigDecimal amount) {
        this.fromAccount = from; this.toAccount = to; this.amount = amount;
    }
    String getFromAccount() { return fromAccount; }
    String toJson() {
        return "{\"from\":\"" + fromAccount + "\",\"to\":\"" + toAccount
                + "\",\"amount\":" + amount + "}";
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
